const b = $input.first().json.body || $input.first().json;
const clean = s => (s ?? '').toString().trim();
const email = clean(b.email).toLowerCase();
const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email);
const free = ['gmail.com','yahoo.com','outlook.com','hotmail.com','icloud.com','proton.me','live.com'];
const domain = email.split('@')[1] || '';
const fullName = clean(b.name);
const parts = fullName.split(/\s+/).filter(Boolean);
return [{ json: {
  valid: emailOk && parts.length > 0,
  errors: [...(emailOk ? [] : ['invalid_email']), ...(parts.length ? [] : ['missing_name'])],
  firstName: parts.length > 1 ? parts[0] : '',
  lastName: parts.length > 1 ? parts.slice(1).join(' ') : (parts[0] || ''),
  fullName, email, domain, isFreeMail: free.includes(domain),
  phone: clean(b.phone), company: clean(b.company),
  message: clean(b.message).slice(0, 2000),
  source: clean(b.source) || 'Web Form',
  receivedAt: new Date().toISOString()
}}];

const base = $('Validate & Normalize').first().json;
const j = $input.first().json || {};
let enrich = { provider: 'none', title: '', seniority: '', linkedin: '', companyName: '', industry: '', employees: null };
if (j.person) {
  const p = j.person, o = p.organization || {};
  enrich = { provider: 'apollo', title: p.title || '', seniority: p.seniority || '', linkedin: p.linkedin_url || '',
             companyName: o.name || '', industry: o.industry || '', employees: o.estimated_num_employees || null };
} else if (j.data && !j.error) {
  const d = j.data;
  enrich = { provider: 'hunter', title: d.employment?.title || d.position || '',
             seniority: d.employment?.seniority || '',
             linkedin: d.linkedin?.handle ? `https://linkedin.com/in/${d.linkedin.handle}` : '',
             companyName: d.employment?.name || '', industry: '', employees: null };
}
return [{ json: { ...base, enrich } }];

function rules(l) {
  let s = 20;
  if (!l.isFreeMail) s += 20;
  if (l.company) s += 10;
  if (l.phone) s += 10;
  if (/budget|quote|pricing|demo|urgent|asap|proposal|hire/i.test(l.message)) s += 20;
  if (/(ceo|founder|owner|director|head|vp|chief|manager)/i.test(l.enrich.title || '')) s += 15;
  if ((l.enrich.employees || 0) >= 50) s += 5;
  s = Math.min(s, 100);
  return { score: s, tier: s >= 75 ? 'hot' : s >= 45 ? 'warm' : 'cold', confidence: 0.4,
           summary: 'Rule-based score (AI unavailable)', nextAction: 'Review manually', spam: false, scoringMode: 'rules' };
}

const l = $('Consolidate Enrichment').first().json;
let r = null;
try { r = JSON.parse($input.first().json.choices[0].message.content); } catch (e) {}
if (!r || typeof r.score !== 'number' || !['hot','warm','cold'].includes(r.tier)) {
  return [{ json: rules(l) }];   // fallback if AI output is malformed
}
return [{ json: { score: r.score, tier: r.tier, confidence: Number(r.confidence ?? 0.7), summary: r.summary || '',
                  nextAction: r.nextAction || '', spam: !!r.spam, scoringMode: 'ai' } }];

