  if (/(ceo|founder|owner|director|head|vp|chief|manager)/i.test(l.enrich.title || '')) s += 15;
  if ((l.enrich.employees || 0) >= 50) s += 5;
  s = Math.min(s, 100);
  return { score: s, tier: s >= 75 ? 'hot' : s >= 45 ? 'warm' : 'cold', confidence: 0.4,
           summary: 'Rule-based score (AI unavailable)', nextAction: 'Review manually', spam: false, scoringMode: 'rules' };
}

const l = $('Consolidate Enrichment').first().json;
return [{ json: rules(l) }];

const l = $('Consolidate Enrichment').first().json;
const s = $input.first().json;
const tier = s.spam ? 'cold' : s.tier;
const needsReview = !s.spam && (tier === 'hot' || s.confidence < 0.5);
const desc = [
  `AI score: ${s.score}/100 (${tier}) [${s.scoringMode}]`,
  s.summary,
  `Next action: ${s.nextAction}`,
  `Source: ${l.source}`,
  l.message ? `Message: ${l.message}` : '',
  l.enrich.linkedin ? `LinkedIn: ${l.enrich.linkedin}` : '',
  `Enrichment: ${l.enrich.provider}`
].filter(Boolean).join('\n');
const record = {
  Last_Name: l.lastName || l.fullName,
  First_Name: l.firstName || undefined,
  Email: l.email,
  Phone: l.phone || undefined,
  Company: l.company || l.enrich.companyName || 'Unknown',
  Designation: l.enrich.title || undefined,
  Industry: l.enrich.industry || undefined,
  Lead_Status: tier === 'hot' ? 'Pre-Qualified' : tier === 'warm' ? 'Not Contacted' : 'Contact in Future',
  Description: desc
};
return [{ json: { l, ai: s, tier, needsReview, record,
  zohoBody: { data: [record], duplicate_check_fields: ['Email'], trigger: ['workflow'] } } }];

