const p = $('Build Zoho Payload').first().json;
const approved = $input.first().json?.data?.approved === true;   // timeout / decline => false
const rec = { ...p.record };
rec.Lead_Status = approved ? 'Pre-Qualified' : 'Contact in Future';
rec.Description += `\nHITL decision: ${approved ? 'APPROVED' : 'DECLINED / no response'}`;
return [{ json: { ...p, approved, tier: approved ? p.tier : 'warm', record: rec,
  zohoBody: { data: [rec], duplicate_check_fields: ['Email'], trigger: ['workflow'] } } }];

const p = $('Apply HITL Decision').isExecuted ? $('Apply HITL Decision').first().json : $('Build Zoho Payload').first().json;

const r = $input.first().json?.data?.[0] || {};
const ok = r.code === 'SUCCESS';
return [{ json: { ...p, zoho: { ok, id: r.details?.id, action: r.action, code: r.code, message: r.message } } }];

const p = $input.first().json;
const due = new Date(Date.now() + 24 * 3600 * 1000).toISOString().slice(0, 10);
return [{ json: { ...p, taskBody: { data: [{
  Subject: `Call hot lead: ${p.l.fullName} (${p.l.company || 'n/a'})`,
  Due_Date: due, Priority: 'High', Status: 'Not Started',
  Description: p.ai.summary, What_Id: { id: p.zoho.id }, '$se_module': 'Leads'
}] } } }];

const p = $('Apply HITL Decision').isExecuted ? $('Apply HITL Decision').first().json : $('Build Zoho Payload').first().json;

const j = $input.first().json;
const reason = j.zoho ? `${j.zoho.code}: ${j.zoho.message}` : (j.error?.message || j.error || j.message || 'Unknown Zoho error');
return [{ json: { queuedAt: new Date().toISOString(), email: p.l.email, name: p.l.fullName, tier: p.tier,
  score: p.ai.score, reason: String(reason).slice(0, 500), payload: JSON.stringify(p.zohoBody) } }];

